using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;
using ElementalHearts;using RimWorld;using Verse;using UnityEngine;
class ThunderstormRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static string modRoot;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Set(object o,string key,object value){o.GetType().GetField(key,F).SetValue(o,value);}
 static object Get(object o,string key){return o.GetType().GetField(key,F).GetValue(o);}
 static Pawn PawnWith(HediffWithComps h){var p=Empty<Pawn>();p.health=Empty<Pawn_HealthTracker>();p.health.hediffSet=Empty<HediffSet>();p.health.hediffSet.hediffs=new List<Hediff>{h};h.pawn=p;return p;}
 static HediffWithComps Root(string name){var h=new HediffWithComps();h.def=Empty<HediffDef>();h.def.defName=name;h.def.tags=new List<string>{ElementalHeartUtility.HeartTag};h.comps=new List<HediffComp>();return h;}
 static int Main(string[] args){modRoot=Path.GetDirectoryName(Path.GetDirectoryName(args[1]));AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(ThunderstormRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  var prefs=typeof(Prefs).GetField("data",BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public);object previous=prefs.GetValue(null);bool previousGod=DebugSettings.godMode;var data=Empty<PrefsData>();prefs.SetValue(null,data);try{Set(data,"devMode",true);DebugSettings.godMode=false;var cached=Empty<DevEvolutionReadyCommand>();int fired=0;cached.action=()=>fired++;Check(!cached.Visible,"Developer mode alone reveals Evolution-Ready");DebugSettings.godMode=true;Check(cached.Visible,"Evolution-Ready hidden with God Mode enabled");DebugSettings.godMode=false;Check(!cached.Visible,"Cached Evolution-Ready remains visible after God Mode is turned off");cached.ProcessInput(null);Check(fired==0,"Cached command executed outside God Mode");DebugSettings.godMode=true;Check(cached.Visible,"Evolution-Ready failed to reappear when God Mode is re-enabled");cached.isEligible=()=>false;Check(!cached.Visible,"Cached command remains after its pawn is no longer eligible");}finally{DebugSettings.godMode=previousGod;prefs.SetValue(null,previous);}
  Console.WriteLine("PASS: Evolution-Ready follows God Mode, hides with God Mode off even if developer mode is on, and guards stale command input/eligibility.");
  foreach(int kills in new[]{0,149,150,151})foreach(int ticks in new[]{0,599999,600000,900000})Check(ThunderstormRules.Ready(kills,ticks)==(kills>=150&&ticks>=600000),"Thunderstorm readiness boundaries");Check(ThunderstormRules.MarkCap(99)==3&&ThunderstormRules.MarkCap(-1)==0&&Math.Abs(ThunderstormRules.PulseShare(3)*3-1)<.00001,"Mark or pulse budget cap");
  var root=Root("EH_LightningHeart");var pawn=PawnWith(root);root.loadID=717;root.ageTicks=777777;Set(root,"severityInt",1.25f);var abilities=new HediffComp_LightningAbilities{autoCombat=true,nonLethal=true,parent=root,props=new HediffCompProperties_LightningAbilities()};var ready=(List<int>)Get(abilities,"readyAt");ready[2]=54321;var transform=new HediffComp_ElementalTransform{parent=root,props=new HediffCompProperties_ElementalTransform(),transformed=true};var oldKit=Get(transform,"kit");var passive=new HediffComp_LightningPassives{parent=root,props=new HediffCompProperties_LightningPassives()};Set(passive,"counterReadyAt",8765);var mastery=new HediffComp_ThunderstormMastery{parent=root,props=new HediffCompProperties_ThunderstormMastery(),kills=153};root.comps.AddRange(new HediffComp[]{abilities,transform,passive,mastery});
  var evolved=Empty<HediffDef>();evolved.defName=ThunderstormEvolution.DefName;evolved.tags=new List<string>{ElementalHeartUtility.HeartTag};evolved.comps=new List<HediffCompProperties>{new HediffCompProperties_ElementalTransform(),new HediffCompProperties_LightningAbilities(),new HediffCompProperties_LightningPassives(),new HediffCompProperties_ThunderstormMastery(),new HediffCompProperties_ThunderstormHalo(),new HediffCompProperties_TempestCircuit()};AzureLineage.Rebind(root,evolved);
  Check(root.loadID==717&&root.ageTicks==777777&&root.Severity==1.25f&&root.def==evolved&&root.TryGetComp<HediffComp_LightningAbilities>()==abilities&&object.ReferenceEquals(ready,Get(abilities,"readyAt"))&&ready[2]==54321&&abilities.autoCombat&&abilities.nonLethal,"Evolution resets saved identity/ability state");Check(root.TryGetComp<HediffComp_ElementalTransform>()==transform&&transform.transformed&&object.ReferenceEquals(oldKit,Get(transform,"kit"))&&(int)Get(passive,"counterReadyAt")==8765&&mastery.kills==153,"Evolution resets transformation/passive/mastery state");
  var circuit=root.TryGetComp<HediffComp_TempestCircuit>();Check(circuit!=null,"Fifth ability missing");circuit.readyAt=9876;AzureLineage.Rebind(root,evolved);Check(root.comps.Count==6&&root.TryGetComp<HediffComp_TempestCircuit>()==circuit&&circuit.readyAt==9876,"Repeat binding duplicates or resets fifth slot");Check(ThunderstormEvolution.Active(pawn)&&ThunderstormEvolution.HasLightning(pawn)&&ElementalHeartUtility.HasHeart(pawn)&&ElementalTeaching.Element(pawn)=="Lightning"&&abilities.Props==ThunderstormEvolution.Tuning,"Standalone Lightning lineage/teaching/tuning identity lost");
  foreach(var suffix in new[]{"Uniform","Sword"}){var d=Empty<ThingDef>();d.defName="EH_Thunderstorm"+suffix;DefDatabase<ThingDef>.Add(d);}Check((bool)typeof(HediffComp_ElementalTransform).GetProperty("Available",F).GetValue(transform,null),"Thunderstorm gear still requires a helmet");Check((string)typeof(HediffComp_ElementalTransform).GetProperty("EquipmentElement",F).GetValue(transform,null)=="Thunderstorm","Wrong evolved kit selection");
  var kill=new HediffComp_ThunderstormMastery{parent=root};var record=typeof(HediffComp_ThunderstormMastery).GetMethod("RecordKill",F);Check((bool)record.Invoke(kill,new object[]{101,true})&&!(bool)record.Invoke(kill,new object[]{101,true})&&!(bool)record.Invoke(kill,new object[]{102,false})&&kill.kills==1,"Unique kill tracking");typeof(HediffComp_ThunderstormMastery).GetMethod("MakeEvolutionReady",F).Invoke(kill,null);Check(kill.kills==150&&root.ageTicks>=600000,"DEV readiness does not set milestones");kill.kills=200;typeof(HediffComp_ThunderstormMastery).GetMethod("MakeEvolutionReady",F).Invoke(kill,null);Check(kill.kills==200,"DEV readiness lowers progress");
  Console.WriteLine("PASS: standalone Thunderstorm rebinding preserves original hediff ID/age/severity, four cooldowns, automation, transform kit, passive timers, mastery and fifth-slot cooldown; helmet-free kit, Lightning teaching and unique milestones.");
  var ordinary=PawnWith(Root("EH_LightningHeart"));var azure=PawnWith(Root(AzureEvolution.DefName));var normalHit=new DamageInfo(null,100,0,-1,ordinary);AzureAscendantWard.Prefix(pawn,ref normalHit);Check(normalHit.Amount==25,"Thunderstorm lacks normal-ascendant ward");var peer1=new DamageInfo(null,100,0,-1,pawn);AzureAscendantWard.Prefix(azure,ref peer1);var peer2=new DamageInfo(null,100,0,-1,azure);AzureAscendantWard.Prefix(pawn,ref peer2);Check(peer1.Amount==100&&peer2.Amount==100,"Evolved peers receive asymmetric extra ward");var worker=new ThoughtWorker_ThunderstormResolve();var state=(ThoughtState)typeof(ThoughtWorker_ThunderstormResolve).GetMethod("CurrentStateInternal",F).Invoke(worker,new object[]{pawn});var thought=Empty<ThoughtDef>();thought.stages=new List<ThoughtStage>{new ThoughtStage{baseMoodEffect=30},new ThoughtStage{baseMoodEffect=50}};Check(state.StageIndexFor(thought)==1,"Thunderstorm +50 mood replacement");
  var p1=Empty<Pawn>();p1.thingIDNumber=1;var p2=Empty<Pawn>();p2.thingIDNumber=2;var p3=Empty<Pawn>();p3.thingIDNumber=3;var p4=Empty<Pawn>();p4.thingIDNumber=4;var candidates=new List<Pawn>{p1,p1,p2,p3,p4};Check(MapComponent_Thunderstorm.SelectTargets(candidates,true).Count==3&&MapComponent_Thunderstorm.SelectTargets(candidates,false).Count==4,"Pulse target budget/duplicate guard");var red=EvolutionTimeline.Accent(true,1);var blue=EvolutionTimeline.Accent(false,1);Check(red.r>.9f&&red.b<.2f&&blue.b>.9f&&blue.r<.2f,"Procedural evolution colors incorrect");Check(ElementalBalance.Affected("EH_ThunderstormDamage",false,true),"Storm damage bypasses existing nerf");
  Console.WriteLine("PASS: normal-ascendant defense and symmetric Azure/Thunderstorm peer treatment, +50 mood, bounded/deduplicated circuit targets, shared pulse budget and procedural red palette.");
  var payload=new ThunderSaveCase{zone=new ThunderstormZone{cell=new IntVec3(7,0,8),circuit=true,due=1234,pulses=2,damage=15,physical=1,electrical=1.4f},mastery=kill,circuit=circuit};string file=Path.Combine(Path.GetTempPath(),"ThunderTest_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"ThunderTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectSingleNode("ThunderTest/state/zone/due").InnerText=="1234"&&xml.SelectSingleNode("ThunderTest/state/zone/pulses").InnerText=="2"&&xml.SelectSingleNode("ThunderTest/state/EH_tempestCircuitReadyAt").InnerText=="9876"&&xml.SelectSingleNode("ThunderTest/state/EH_stormMasteryVictims/li").InnerText=="101","Native save output loses pending zones, cooldown or unique victims");File.Delete(file);
  Check(!Directory.Exists(Path.Combine(modRoot,"Textures/Effects/ElementalHearts/Azure/Evolution"))||Directory.GetFiles(Path.Combine(modRoot,"Textures/Effects/ElementalHearts/Azure/Evolution"),"*.png").Length==0,"Removed evolution assets remain");Check(!Directory.Exists(Path.Combine(modRoot,"Textures/Effects/ElementalHearts/Azure/Manifestation"))||Directory.GetFiles(Path.Combine(modRoot,"Textures/Effects/ElementalHearts/Azure/Manifestation"),"*.png").Length==0,"Removed manifestation assets remain");Check(typeof(MapComponent_AzureManifestation).GetMethod("MapComponentDraw").DeclaringType==typeof(MapComponent),"Legacy save shim still draws removed effects");Check(ManifestationRules.Coverage(90,false)==0&&ManifestationRules.Coverage(30,false)==1,"Smooth apparel reveal not restored");
  Console.WriteLine("PASS: native Scribe save output for zones/pulses, cooldown and unique mastery victims; rejected textures absent, harmless old-save component retained and original apparel reveal restored. Native load/live rendering not exercised.");
 }
}
public class ThunderSaveCase:IExposable {public ThunderstormZone zone;public HediffComp_ThunderstormMastery mastery;public HediffComp_TempestCircuit circuit;public void ExposeData(){Scribe_Deep.Look(ref zone,"zone");mastery.CompExposeData();circuit.CompExposeData();}}
